Section F16I.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x8 x9 x10 x11 x12 x14 x15 x16 x19 x20 x21 x22 x23 x24 x25 x27 x28 x29 : word).
  Variables (m : fmem) (DT SY V len b nb : Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat)
            (cells0 : list (option deltX1)).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HB : 0 <= b < 256.
  Hypothesis HNB : 0 <= nb < 16.
  Hypothesis HV : 0 <= V.
  Hypothesis HLEN : 16 <= len /\ len mod 16 = 0.
  Hypothesis HVL : V + len <= Z.of_nat ncells.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 2 * Z.of_nat ncells <= 2^47.
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis HSP : DT + 4 + 2 * Z.of_nat ncells <= SP /\ SP + 64 <= 2^64.
  Hypothesis HSY : 0 < SY /\ SY + zlen js <= 2^64.
  Hypothesis LC0 : length cells0 = ncells.
  Notation INV m1 cells := (x1f_inv m m1 DT SY js jt syms ncells cells).
  Notation C := (mkX1 nb b).

  Lemma f16_in : forall j k (x5 x7 x13 x17 x18 x30 x31 : word) m1,
    Z.of_nat j = len / 16 - k -> 0 <= k < len / 16 ->
    INV m1 (updc cells0 (seq (Z.to_nat V) (Z.to_nat (16 * k))) C) ->
    (forall m2 (y5 y7 y13 y17 y18 y30 y31 : word),
       INV m2 (updc cells0 (seq (Z.to_nat V) (Z.to_nat len)) C) ->
       evt psegs POST (MS (mkR (Z_to_bv 64 (DT + 20 + 2 * (V + len))) sp gp tp y5 (Z_to_bv 64 (rep_val b nb)) y7 x8 x9
                               x10 x11 x12 y13 x14 x15 x16 y17 y18 x19 x20 x21 x22 x23 x24 x25
                               (Z_to_bv 64 (DT + 20 + 2 * (V + len))) x27 x28 x29 y30 y31)
                          F (Z_to_bv 64 0x13918) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR (Z_to_bv 64 (DT + 20 + 2 * (V + len))) sp gp tp x5 (Z_to_bv 64 (rep_val b nb)) x7 x8 x9
                            x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25
                            (Z_to_bv 64 (DT + 20 + 2 * (V + 16 * k))) x27 x28 x29 x30 x31)
